// generate-log002-cover — the cover for the contact-form record.
//
// NOT generated by `npm run cover`. That script draws one staircase and swaps
// the words, which is right for a post with no artwork of its own and wrong
// here: this post has the two-pipes diagram, and CLAUDE.md §3 says to build the
// cover out of the post's own artwork when it has some. Two covers that differ
// only in wording is a failure of the cover, not a success of the system.
//
// A cover is a poster, not a slide. So this is the convergence reduced to its
// bare shape — two lines becoming one — plus the address that did not resolve
// before this episode. No record number in the artwork (§3): the feed row, the
// stamp and the OG card all print it beside the image already, and baking it in
// freezes it into a raster the day the record is renumbered.
//
//   node scripts/generate-log002-cover.mjs && npm run tiles
import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { BOX, COLOR, SIZE, OP, text, liveNode, chassis, open, assertFits } from '../src/lib/tile-system.mjs';

const OUT = 'content/log/2026/contact-form-and-domain-email/assets/thumb.svg';

// --- the poster -----------------------------------------------------------
const NODE = { x: 1010, y: 520, r: 34, halo: 90 };
const LINE_A_Y = 396; // sending
const LINE_B_Y = 644; // receiving

// 45° again, so the cover and the in-post tile are visibly the same drawing.
// The elbow is derived from the drop, never chosen.
const END_X = NODE.x - NODE.halo - 12;
const DROP_A = NODE.y - LINE_A_Y;
const DROP_B = LINE_B_Y - NODE.y;
if (DROP_A !== DROP_B) {
  throw new Error(`[cover] lines are not symmetric about the node (${DROP_A} vs ${DROP_B}); the elbows would not mirror.`);
}
const ELBOW_X = END_X - DROP_A;

const STAMP = 'SETTLED · BUILD LOG';
const WORDMARK = 'hello@deadlinklabs.com';

assertFits('stamp', STAMP, SIZE.eyebrow, 2, BOX.left);
assertFits('wordmark', WORDMARK, 64, 0, BOX.left);
if (NODE.x + NODE.halo > BOX.right) {
  throw new Error(`[cover] the live node's halo crosses the rail at ${NODE.x + NODE.halo}.`);
}

const line = (y) =>
  `<path d="M ${BOX.left} ${y} H ${ELBOW_X} L ${END_X} ${NODE.y}" fill="none" stroke="${COLOR.ink}" stroke-opacity="0.5" stroke-width="4"/>`;

const svg = `${open()}
  ${chassis()}
  ${text(STAMP, { x: BOX.left, y: 100, size: SIZE.eyebrow, ls: 2, op: OP.eyebrow })}
  ${text(WORDMARK, { x: BOX.left, y: 252, size: 64, op: OP.hero })}
  ${line(LINE_A_Y)}
  ${line(LINE_B_Y)}
  ${liveNode(NODE.x, NODE.y, { r: NODE.r, halo: NODE.halo })}
</svg>
`;

mkdirSync(dirname(OUT), { recursive: true });
writeFileSync(OUT, svg);
console.log(`[cover] wrote ${OUT} — now run: npm run tiles`);
